document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".zee-timeline-item"),t=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),t.unobserve(e.target))})},{root:null,rootMargin:"0px",threshold:.2});e.forEach(e=>{t.observe(e)}),setTimeout(()=>{e.forEach(e=>{e.getBoundingClientRect().top<window.innerHeight&&(e.classList.add("visible"),t.unobserve(e))})},100)});